/* PROTOTYPE, NEVER COMPILED: Linux shim using an X11 fullscreen window and Vulkan. */
#define VK_USE_PLATFORM_XLIB_KHR
#include <X11/Xatom.h>
#include <X11/Xlib.h>
#include <X11/Xutil.h>
#include <X11/keysym.h>
#include <stdlib.h>
#include <string.h>
#include <vulkan/vulkan.h>
#include "oe_shim.h"
#include "quad_spv.h" /* generated by build.rs with glslc */

enum { MAX_IMAGES = 8, FRAMES = 2 };

static Display *g_display;
static Window g_window;
static Atom g_wm_delete;
static Cursor g_blank_cursor;
static int32_t g_width, g_height;

static VkInstance g_instance;
static VkSurfaceKHR g_surface;
static VkPhysicalDevice g_gpu;
static VkDevice g_device;
static uint32_t g_queue_family;
static VkQueue g_queue;
static VkRenderPass g_pass;
static VkPipelineLayout g_layout;
static VkPipeline g_pipeline;
static VkCommandPool g_pool;

static VkSwapchainKHR g_swapchain;
static VkFormat g_format;
static VkExtent2D g_extent;
static uint32_t g_image_count;
static VkImage g_images[MAX_IMAGES];
static VkImageView g_views[MAX_IMAGES];
static VkFramebuffer g_framebuffers[MAX_IMAGES];
static VkSemaphore g_render_done[MAX_IMAGES];

typedef struct {
    VkCommandBuffer commands;
    VkSemaphore image_ready;
    VkFence fence;
    VkBuffer buffer;
    VkDeviceMemory memory;
    void *mapped;
    VkDeviceSize capacity;
} Frame;

static Frame g_frames[FRAMES];
static uint32_t g_frame;

static uint32_t find_memory(uint32_t type_bits, VkMemoryPropertyFlags flags) {
    VkPhysicalDeviceMemoryProperties props;
    vkGetPhysicalDeviceMemoryProperties(g_gpu, &props);
    for (uint32_t i = 0; i < props.memoryTypeCount; i++) {
        if ((type_bits & (1u << i)) && (props.memoryTypes[i].propertyFlags & flags) == flags) return i;
    }
    return UINT32_MAX;
}

static void destroy_swapchain_objects(void) {
    for (uint32_t i = 0; i < g_image_count; i++) {
        vkDestroyFramebuffer(g_device, g_framebuffers[i], NULL);
        vkDestroyImageView(g_device, g_views[i], NULL);
        vkDestroySemaphore(g_device, g_render_done[i], NULL);
    }
    g_image_count = 0;
}

static int create_swapchain(void) {
    VkSurfaceCapabilitiesKHR caps;
    vkGetPhysicalDeviceSurfaceCapabilitiesKHR(g_gpu, g_surface, &caps);
    g_extent = caps.currentExtent;
    if (g_extent.width == UINT32_MAX) {
        g_extent.width = (uint32_t)g_width;
        g_extent.height = (uint32_t)g_height;
    }
    uint32_t wanted = caps.minImageCount + 1;
    if (caps.maxImageCount && wanted > caps.maxImageCount) wanted = caps.maxImageCount;
    if (wanted > MAX_IMAGES) wanted = MAX_IMAGES;

    VkSwapchainKHR old = g_swapchain;
    VkSwapchainCreateInfoKHR info = {VK_STRUCTURE_TYPE_SWAPCHAIN_CREATE_INFO_KHR};
    info.surface = g_surface;
    info.minImageCount = wanted;
    info.imageFormat = g_format;
    info.imageColorSpace = VK_COLOR_SPACE_SRGB_NONLINEAR_KHR;
    info.imageExtent = g_extent;
    info.imageArrayLayers = 1;
    info.imageUsage = VK_IMAGE_USAGE_COLOR_ATTACHMENT_BIT;
    info.imageSharingMode = VK_SHARING_MODE_EXCLUSIVE;
    info.preTransform = caps.currentTransform;
    info.compositeAlpha = VK_COMPOSITE_ALPHA_OPAQUE_BIT_KHR;
    info.presentMode = VK_PRESENT_MODE_FIFO_KHR;
    info.clipped = VK_TRUE;
    info.oldSwapchain = old;
    if (vkCreateSwapchainKHR(g_device, &info, NULL, &g_swapchain) != VK_SUCCESS) return 0;
    if (old) vkDestroySwapchainKHR(g_device, old, NULL);

    g_image_count = MAX_IMAGES;
    vkGetSwapchainImagesKHR(g_device, g_swapchain, &g_image_count, g_images);
    for (uint32_t i = 0; i < g_image_count; i++) {
        VkImageViewCreateInfo view = {VK_STRUCTURE_TYPE_IMAGE_VIEW_CREATE_INFO};
        view.image = g_images[i];
        view.viewType = VK_IMAGE_VIEW_TYPE_2D;
        view.format = g_format;
        view.subresourceRange.aspectMask = VK_IMAGE_ASPECT_COLOR_BIT;
        view.subresourceRange.levelCount = 1;
        view.subresourceRange.layerCount = 1;
        vkCreateImageView(g_device, &view, NULL, &g_views[i]);

        VkFramebufferCreateInfo fb = {VK_STRUCTURE_TYPE_FRAMEBUFFER_CREATE_INFO};
        fb.renderPass = g_pass;
        fb.attachmentCount = 1;
        fb.pAttachments = &g_views[i];
        fb.width = g_extent.width;
        fb.height = g_extent.height;
        fb.layers = 1;
        vkCreateFramebuffer(g_device, &fb, NULL, &g_framebuffers[i]);

        VkSemaphoreCreateInfo sem = {VK_STRUCTURE_TYPE_SEMAPHORE_CREATE_INFO};
        vkCreateSemaphore(g_device, &sem, NULL, &g_render_done[i]);
    }
    return 1;
}

static void recreate_swapchain(void) {
    vkDeviceWaitIdle(g_device);
    destroy_swapchain_objects();
    create_swapchain();
}

static VkShaderModule make_shader(const uint32_t *code, size_t bytes) {
    VkShaderModuleCreateInfo info = {VK_STRUCTURE_TYPE_SHADER_MODULE_CREATE_INFO};
    info.codeSize = bytes;
    info.pCode = code;
    VkShaderModule module = VK_NULL_HANDLE;
    vkCreateShaderModule(g_device, &info, NULL, &module);
    return module;
}

static int create_pipeline(void) {
    VkAttachmentDescription attachment = {0};
    attachment.format = g_format;
    attachment.samples = VK_SAMPLE_COUNT_1_BIT;
    attachment.loadOp = VK_ATTACHMENT_LOAD_OP_CLEAR;
    attachment.storeOp = VK_ATTACHMENT_STORE_OP_STORE;
    attachment.stencilLoadOp = VK_ATTACHMENT_LOAD_OP_DONT_CARE;
    attachment.stencilStoreOp = VK_ATTACHMENT_STORE_OP_DONT_CARE;
    attachment.initialLayout = VK_IMAGE_LAYOUT_UNDEFINED;
    attachment.finalLayout = VK_IMAGE_LAYOUT_PRESENT_SRC_KHR;
    VkAttachmentReference ref = {0, VK_IMAGE_LAYOUT_COLOR_ATTACHMENT_OPTIMAL};
    VkSubpassDescription subpass = {0};
    subpass.pipelineBindPoint = VK_PIPELINE_BIND_POINT_GRAPHICS;
    subpass.colorAttachmentCount = 1;
    subpass.pColorAttachments = &ref;
    VkSubpassDependency dep = {0};
    dep.srcSubpass = VK_SUBPASS_EXTERNAL;
    dep.srcStageMask = VK_PIPELINE_STAGE_COLOR_ATTACHMENT_OUTPUT_BIT;
    dep.dstStageMask = VK_PIPELINE_STAGE_COLOR_ATTACHMENT_OUTPUT_BIT;
    dep.dstAccessMask = VK_ACCESS_COLOR_ATTACHMENT_WRITE_BIT;
    VkRenderPassCreateInfo pass = {VK_STRUCTURE_TYPE_RENDER_PASS_CREATE_INFO};
    pass.attachmentCount = 1;
    pass.pAttachments = &attachment;
    pass.subpassCount = 1;
    pass.pSubpasses = &subpass;
    pass.dependencyCount = 1;
    pass.pDependencies = &dep;
    if (vkCreateRenderPass(g_device, &pass, NULL, &g_pass) != VK_SUCCESS) return 0;

    VkPushConstantRange push = {VK_SHADER_STAGE_VERTEX_BIT, 0, sizeof(float) * 2};
    VkPipelineLayoutCreateInfo layout = {VK_STRUCTURE_TYPE_PIPELINE_LAYOUT_CREATE_INFO};
    layout.pushConstantRangeCount = 1;
    layout.pPushConstantRanges = &push;
    if (vkCreatePipelineLayout(g_device, &layout, NULL, &g_layout) != VK_SUCCESS) return 0;

    VkShaderModule vert = make_shader(quad_vert_spv, sizeof(quad_vert_spv));
    VkShaderModule frag = make_shader(quad_frag_spv, sizeof(quad_frag_spv));
    VkPipelineShaderStageCreateInfo stages[2] = {
        {VK_STRUCTURE_TYPE_PIPELINE_SHADER_STAGE_CREATE_INFO, NULL, 0, VK_SHADER_STAGE_VERTEX_BIT, vert, "main", NULL},
        {VK_STRUCTURE_TYPE_PIPELINE_SHADER_STAGE_CREATE_INFO, NULL, 0, VK_SHADER_STAGE_FRAGMENT_BIT, frag, "main", NULL},
    };
    VkVertexInputBindingDescription binding = {0, sizeof(OeVertex), VK_VERTEX_INPUT_RATE_VERTEX};
    VkVertexInputAttributeDescription attributes[2] = {
        {0, 0, VK_FORMAT_R32G32_SFLOAT, 0},
        {1, 0, VK_FORMAT_R32G32B32A32_SFLOAT, 8},
    };
    VkPipelineVertexInputStateCreateInfo input = {VK_STRUCTURE_TYPE_PIPELINE_VERTEX_INPUT_STATE_CREATE_INFO};
    input.vertexBindingDescriptionCount = 1;
    input.pVertexBindingDescriptions = &binding;
    input.vertexAttributeDescriptionCount = 2;
    input.pVertexAttributeDescriptions = attributes;
    VkPipelineInputAssemblyStateCreateInfo assembly = {VK_STRUCTURE_TYPE_PIPELINE_INPUT_ASSEMBLY_STATE_CREATE_INFO};
    assembly.topology = VK_PRIMITIVE_TOPOLOGY_TRIANGLE_LIST;
    VkPipelineViewportStateCreateInfo viewport = {VK_STRUCTURE_TYPE_PIPELINE_VIEWPORT_STATE_CREATE_INFO};
    viewport.viewportCount = 1;
    viewport.scissorCount = 1;
    VkPipelineRasterizationStateCreateInfo raster = {VK_STRUCTURE_TYPE_PIPELINE_RASTERIZATION_STATE_CREATE_INFO};
    raster.polygonMode = VK_POLYGON_MODE_FILL;
    raster.cullMode = VK_CULL_MODE_NONE;
    raster.lineWidth = 1.0f;
    VkPipelineMultisampleStateCreateInfo multisample = {VK_STRUCTURE_TYPE_PIPELINE_MULTISAMPLE_STATE_CREATE_INFO};
    multisample.rasterizationSamples = VK_SAMPLE_COUNT_1_BIT;
    VkPipelineColorBlendAttachmentState blend_attachment = {0};
    blend_attachment.blendEnable = VK_TRUE;
    blend_attachment.srcColorBlendFactor = VK_BLEND_FACTOR_SRC_ALPHA;
    blend_attachment.dstColorBlendFactor = VK_BLEND_FACTOR_ONE_MINUS_SRC_ALPHA;
    blend_attachment.colorBlendOp = VK_BLEND_OP_ADD;
    blend_attachment.srcAlphaBlendFactor = VK_BLEND_FACTOR_ONE;
    blend_attachment.dstAlphaBlendFactor = VK_BLEND_FACTOR_ONE_MINUS_SRC_ALPHA;
    blend_attachment.alphaBlendOp = VK_BLEND_OP_ADD;
    blend_attachment.colorWriteMask = VK_COLOR_COMPONENT_R_BIT | VK_COLOR_COMPONENT_G_BIT |
                                      VK_COLOR_COMPONENT_B_BIT | VK_COLOR_COMPONENT_A_BIT;
    VkPipelineColorBlendStateCreateInfo blend = {VK_STRUCTURE_TYPE_PIPELINE_COLOR_BLEND_STATE_CREATE_INFO};
    blend.attachmentCount = 1;
    blend.pAttachments = &blend_attachment;
    VkDynamicState dynamic_states[2] = {VK_DYNAMIC_STATE_VIEWPORT, VK_DYNAMIC_STATE_SCISSOR};
    VkPipelineDynamicStateCreateInfo dynamic = {VK_STRUCTURE_TYPE_PIPELINE_DYNAMIC_STATE_CREATE_INFO};
    dynamic.dynamicStateCount = 2;
    dynamic.pDynamicStates = dynamic_states;

    VkGraphicsPipelineCreateInfo info = {VK_STRUCTURE_TYPE_GRAPHICS_PIPELINE_CREATE_INFO};
    info.stageCount = 2;
    info.pStages = stages;
    info.pVertexInputState = &input;
    info.pInputAssemblyState = &assembly;
    info.pViewportState = &viewport;
    info.pRasterizationState = &raster;
    info.pMultisampleState = &multisample;
    info.pColorBlendState = &blend;
    info.pDynamicState = &dynamic;
    info.layout = g_layout;
    info.renderPass = g_pass;
    VkResult result = vkCreateGraphicsPipelines(g_device, VK_NULL_HANDLE, 1, &info, NULL, &g_pipeline);
    vkDestroyShaderModule(g_device, vert, NULL);
    vkDestroyShaderModule(g_device, frag, NULL);
    return result == VK_SUCCESS;
}

static int init_vulkan(void) {
    const char *instance_extensions[] = {VK_KHR_SURFACE_EXTENSION_NAME, VK_KHR_XLIB_SURFACE_EXTENSION_NAME};
    VkApplicationInfo app = {VK_STRUCTURE_TYPE_APPLICATION_INFO};
    app.pApplicationName = "OpenEmperor";
    app.apiVersion = VK_API_VERSION_1_0;
    VkInstanceCreateInfo instance = {VK_STRUCTURE_TYPE_INSTANCE_CREATE_INFO};
    instance.pApplicationInfo = &app;
    instance.enabledExtensionCount = 2;
    instance.ppEnabledExtensionNames = instance_extensions;
    if (vkCreateInstance(&instance, NULL, &g_instance) != VK_SUCCESS) return 0;

    VkXlibSurfaceCreateInfoKHR surface = {VK_STRUCTURE_TYPE_XLIB_SURFACE_CREATE_INFO_KHR};
    surface.dpy = g_display;
    surface.window = g_window;
    if (vkCreateXlibSurfaceKHR(g_instance, &surface, NULL, &g_surface) != VK_SUCCESS) return 0;

    uint32_t gpu_count = 16;
    VkPhysicalDevice gpus[16];
    vkEnumeratePhysicalDevices(g_instance, &gpu_count, gpus);
    for (uint32_t i = 0; i < gpu_count && !g_gpu; i++) {
        uint32_t family_count = 32;
        VkQueueFamilyProperties families[32];
        vkGetPhysicalDeviceQueueFamilyProperties(gpus[i], &family_count, families);
        for (uint32_t f = 0; f < family_count; f++) {
            VkBool32 present = VK_FALSE;
            vkGetPhysicalDeviceSurfaceSupportKHR(gpus[i], f, g_surface, &present);
            if (present && (families[f].queueFlags & VK_QUEUE_GRAPHICS_BIT)) {
                g_gpu = gpus[i];
                g_queue_family = f;
                break;
            }
        }
    }
    if (!g_gpu) return 0;

    float priority = 1.0f;
    VkDeviceQueueCreateInfo queue = {VK_STRUCTURE_TYPE_DEVICE_QUEUE_CREATE_INFO};
    queue.queueFamilyIndex = g_queue_family;
    queue.queueCount = 1;
    queue.pQueuePriorities = &priority;
    const char *device_extensions[] = {VK_KHR_SWAPCHAIN_EXTENSION_NAME};
    VkDeviceCreateInfo device = {VK_STRUCTURE_TYPE_DEVICE_CREATE_INFO};
    device.queueCreateInfoCount = 1;
    device.pQueueCreateInfos = &queue;
    device.enabledExtensionCount = 1;
    device.ppEnabledExtensionNames = device_extensions;
    if (vkCreateDevice(g_gpu, &device, NULL, &g_device) != VK_SUCCESS) return 0;
    vkGetDeviceQueue(g_device, g_queue_family, 0, &g_queue);

    uint32_t format_count = 32;
    VkSurfaceFormatKHR formats[32];
    vkGetPhysicalDeviceSurfaceFormatsKHR(g_gpu, g_surface, &format_count, formats);
    g_format = VK_FORMAT_B8G8R8A8_UNORM;
    int found = 0;
    for (uint32_t i = 0; i < format_count; i++) {
        if (formats[i].format == VK_FORMAT_B8G8R8A8_UNORM &&
            formats[i].colorSpace == VK_COLOR_SPACE_SRGB_NONLINEAR_KHR) {
            found = 1;
        }
    }
    if (!found) return 0;

    if (!create_pipeline() || !create_swapchain()) return 0;

    VkCommandPoolCreateInfo pool = {VK_STRUCTURE_TYPE_COMMAND_POOL_CREATE_INFO};
    pool.flags = VK_COMMAND_POOL_CREATE_RESET_COMMAND_BUFFER_BIT;
    pool.queueFamilyIndex = g_queue_family;
    vkCreateCommandPool(g_device, &pool, NULL, &g_pool);
    for (int i = 0; i < FRAMES; i++) {
        VkCommandBufferAllocateInfo alloc = {VK_STRUCTURE_TYPE_COMMAND_BUFFER_ALLOCATE_INFO};
        alloc.commandPool = g_pool;
        alloc.level = VK_COMMAND_BUFFER_LEVEL_PRIMARY;
        alloc.commandBufferCount = 1;
        vkAllocateCommandBuffers(g_device, &alloc, &g_frames[i].commands);
        VkSemaphoreCreateInfo sem = {VK_STRUCTURE_TYPE_SEMAPHORE_CREATE_INFO};
        vkCreateSemaphore(g_device, &sem, NULL, &g_frames[i].image_ready);
        VkFenceCreateInfo fence = {VK_STRUCTURE_TYPE_FENCE_CREATE_INFO};
        fence.flags = VK_FENCE_CREATE_SIGNALED_BIT;
        vkCreateFence(g_device, &fence, NULL, &g_frames[i].fence);
    }
    return 1;
}

static void ensure_vertex_buffer(Frame *frame, VkDeviceSize bytes) {
    if (bytes <= frame->capacity) return;
    if (frame->buffer) {
        vkDestroyBuffer(g_device, frame->buffer, NULL);
        vkFreeMemory(g_device, frame->memory, NULL);
    }
    VkBufferCreateInfo buffer = {VK_STRUCTURE_TYPE_BUFFER_CREATE_INFO};
    buffer.size = bytes * 2;
    buffer.usage = VK_BUFFER_USAGE_VERTEX_BUFFER_BIT;
    buffer.sharingMode = VK_SHARING_MODE_EXCLUSIVE;
    vkCreateBuffer(g_device, &buffer, NULL, &frame->buffer);
    VkMemoryRequirements req;
    vkGetBufferMemoryRequirements(g_device, frame->buffer, &req);
    VkMemoryAllocateInfo alloc = {VK_STRUCTURE_TYPE_MEMORY_ALLOCATE_INFO};
    alloc.allocationSize = req.size;
    alloc.memoryTypeIndex =
        find_memory(req.memoryTypeBits, VK_MEMORY_PROPERTY_HOST_VISIBLE_BIT | VK_MEMORY_PROPERTY_HOST_COHERENT_BIT);
    vkAllocateMemory(g_device, &alloc, NULL, &frame->memory);
    vkBindBufferMemory(g_device, frame->buffer, frame->memory, 0);
    vkMapMemory(g_device, frame->memory, 0, VK_WHOLE_SIZE, 0, &frame->mapped);
    frame->capacity = bytes * 2;
}

int32_t oe_init(const char *title, int32_t *width, int32_t *height) {
    g_display = XOpenDisplay(NULL);
    if (!g_display) return 0;
    int screen = DefaultScreen(g_display);
    g_width = DisplayWidth(g_display, screen);
    g_height = DisplayHeight(g_display, screen);
    Window root = RootWindow(g_display, screen);

    g_window = XCreateSimpleWindow(g_display, root, 0, 0, (unsigned)g_width, (unsigned)g_height, 0, 0, 0);
    XStoreName(g_display, g_window, title);
    XSelectInput(g_display, g_window,
                 PointerMotionMask | ButtonPressMask | ButtonReleaseMask | KeyPressMask | StructureNotifyMask |
                     FocusChangeMask);
    g_wm_delete = XInternAtom(g_display, "WM_DELETE_WINDOW", False);
    XSetWMProtocols(g_display, g_window, &g_wm_delete, 1);
    Atom state = XInternAtom(g_display, "_NET_WM_STATE", False);
    Atom fullscreen = XInternAtom(g_display, "_NET_WM_STATE_FULLSCREEN", False);
    XChangeProperty(g_display, g_window, state, XA_ATOM, 32, PropModeReplace, (unsigned char *)&fullscreen, 1);

    char empty = 0;
    XColor black = {0};
    Pixmap blank = XCreateBitmapFromData(g_display, g_window, &empty, 1, 1);
    g_blank_cursor = XCreatePixmapCursor(g_display, blank, blank, &black, &black, 0, 0);
    XFreePixmap(g_display, blank);
    XDefineCursor(g_display, g_window, g_blank_cursor);

    XMapRaised(g_display, g_window);
    XFlush(g_display);

    if (!init_vulkan()) return 0;
    *width = g_width;
    *height = g_height;
    return 1;
}

static void grab_pointer(void) {
    /* confine_to keeps the pointer on this window, so screen edges are real edges. */
    XGrabPointer(g_display, g_window, True, PointerMotionMask | ButtonPressMask | ButtonReleaseMask, GrabModeAsync,
                 GrabModeAsync, g_window, g_blank_cursor, CurrentTime);
}

int32_t oe_poll_event(OeEvent *event) {
    memset(event, 0, sizeof(*event));
    while (XPending(g_display)) {
        XEvent e;
        XNextEvent(g_display, &e);
        switch (e.type) {
            case ClientMessage:
                if ((Atom)e.xclient.data.l[0] == g_wm_delete) {
                    event->kind = OE_EVENT_QUIT;
                    return 1;
                }
                break;
            case FocusIn:
                grab_pointer();
                event->kind = OE_EVENT_FOCUS;
                event->a = 1;
                return 1;
            case FocusOut:
                XUngrabPointer(g_display, CurrentTime);
                event->kind = OE_EVENT_FOCUS;
                event->a = 0;
                return 1;
            case ConfigureNotify:
                if (e.xconfigure.width != g_width || e.xconfigure.height != g_height) {
                    g_width = e.xconfigure.width;
                    g_height = e.xconfigure.height;
                    recreate_swapchain();
                    event->kind = OE_EVENT_RESIZE;
                    event->a = g_width;
                    event->b = g_height;
                    return 1;
                }
                break;
            case MotionNotify:
                event->kind = OE_EVENT_MOUSE_MOVE;
                event->x = (float)e.xmotion.x;
                event->y = (float)e.xmotion.y;
                return 1;
            case ButtonPress:
                /* X11 reports the wheel, and two-finger scrolling, as buttons 4 and 5. */
                if (e.xbutton.button == Button4 || e.xbutton.button == Button5) {
                    event->kind = OE_EVENT_WHEEL;
                    event->y = e.xbutton.button == Button4 ? 1.0f : -1.0f;
                    return 1;
                }
                if (e.xbutton.button != Button1) break;
                event->kind = OE_EVENT_MOUSE_DOWN;
                return 1;
            case ButtonRelease:
                if (e.xbutton.button != Button1) break;
                event->kind = OE_EVENT_MOUSE_UP;
                return 1;
            case KeyPress: {
                KeySym sym = NoSymbol;
                char typed[8];
                int length = XLookupString(&e.xkey, typed, sizeof(typed), &sym, NULL);
                event->kind = OE_EVENT_KEY_DOWN;
                event->a = sym == XK_Escape      ? OE_KEY_ESCAPE
                           : sym == XK_BackSpace ? OE_KEY_BACKSPACE
                           : sym == XK_Return    ? OE_KEY_ENTER
                                                 : OE_KEY_OTHER;
                if (event->a == OE_KEY_OTHER && length == 1 && typed[0] >= 0x20 && typed[0] <= 0x7E) {
                    event->b = typed[0];
                }
                return 1;
            }
            default:
                break;
        }
    }
    return 0;
}

void oe_draw(const OeVertex *vertices, uint32_t count, float r, float g, float b) {
    Frame *frame = &g_frames[g_frame];
    vkWaitForFences(g_device, 1, &frame->fence, VK_TRUE, UINT64_MAX);

    uint32_t image;
    VkResult result = vkAcquireNextImageKHR(g_device, g_swapchain, UINT64_MAX, frame->image_ready, VK_NULL_HANDLE, &image);
    if (result == VK_ERROR_OUT_OF_DATE_KHR) {
        recreate_swapchain();
        return;
    }
    vkResetFences(g_device, 1, &frame->fence);

    if (count) {
        ensure_vertex_buffer(frame, count * sizeof(OeVertex));
        memcpy(frame->mapped, vertices, count * sizeof(OeVertex));
    }

    VkCommandBufferBeginInfo begin = {VK_STRUCTURE_TYPE_COMMAND_BUFFER_BEGIN_INFO};
    begin.flags = VK_COMMAND_BUFFER_USAGE_ONE_TIME_SUBMIT_BIT;
    vkResetCommandBuffer(frame->commands, 0);
    vkBeginCommandBuffer(frame->commands, &begin);

    VkClearValue clear = {{{r, g, b, 1.0f}}};
    VkRenderPassBeginInfo pass = {VK_STRUCTURE_TYPE_RENDER_PASS_BEGIN_INFO};
    pass.renderPass = g_pass;
    pass.framebuffer = g_framebuffers[image];
    pass.renderArea.extent = g_extent;
    pass.clearValueCount = 1;
    pass.pClearValues = &clear;
    vkCmdBeginRenderPass(frame->commands, &pass, VK_SUBPASS_CONTENTS_INLINE);
    if (count) {
        VkViewport viewport = {0, 0, (float)g_extent.width, (float)g_extent.height, 0, 1};
        VkRect2D scissor = {{0, 0}, g_extent};
        float size[2] = {(float)g_extent.width, (float)g_extent.height};
        VkDeviceSize offset = 0;
        vkCmdBindPipeline(frame->commands, VK_PIPELINE_BIND_POINT_GRAPHICS, g_pipeline);
        vkCmdSetViewport(frame->commands, 0, 1, &viewport);
        vkCmdSetScissor(frame->commands, 0, 1, &scissor);
        vkCmdPushConstants(frame->commands, g_layout, VK_SHADER_STAGE_VERTEX_BIT, 0, sizeof(size), size);
        vkCmdBindVertexBuffers(frame->commands, 0, 1, &frame->buffer, &offset);
        vkCmdDraw(frame->commands, count, 1, 0, 0);
    }
    vkCmdEndRenderPass(frame->commands);
    vkEndCommandBuffer(frame->commands);

    VkPipelineStageFlags wait_stage = VK_PIPELINE_STAGE_COLOR_ATTACHMENT_OUTPUT_BIT;
    VkSubmitInfo submit = {VK_STRUCTURE_TYPE_SUBMIT_INFO};
    submit.waitSemaphoreCount = 1;
    submit.pWaitSemaphores = &frame->image_ready;
    submit.pWaitDstStageMask = &wait_stage;
    submit.commandBufferCount = 1;
    submit.pCommandBuffers = &frame->commands;
    submit.signalSemaphoreCount = 1;
    submit.pSignalSemaphores = &g_render_done[image];
    vkQueueSubmit(g_queue, 1, &submit, frame->fence);

    VkPresentInfoKHR present = {VK_STRUCTURE_TYPE_PRESENT_INFO_KHR};
    present.waitSemaphoreCount = 1;
    present.pWaitSemaphores = &g_render_done[image];
    present.swapchainCount = 1;
    present.pSwapchains = &g_swapchain;
    present.pImageIndices = &image;
    result = vkQueuePresentKHR(g_queue, &present);
    if (result == VK_ERROR_OUT_OF_DATE_KHR || result == VK_SUBOPTIMAL_KHR) recreate_swapchain();

    g_frame = (g_frame + 1) % FRAMES;
}

void oe_shutdown(void) {
    if (g_device) {
        vkDeviceWaitIdle(g_device);
        vkDestroyDevice(g_device, NULL);
    }
    if (g_instance) {
        if (g_surface) vkDestroySurfaceKHR(g_instance, g_surface, NULL);
        vkDestroyInstance(g_instance, NULL);
    }
    if (g_display) {
        XUngrabPointer(g_display, CurrentTime);
        XCloseDisplay(g_display);
    }
}
